  String translate(String key) {
    // 1. Check activity-specific translations first
    final actDict = _activityTranslations[_currentLang] ?? _activityTranslations['en'] ?? {};
    if (actDict.containsKey(key)) {
      return actDict[key]!;
    }
    if (_activityTranslations['en']?.containsKey(key) == true) {
      return _activityTranslations['en']![key]!;
    }

    // 2. Check location-specific translations
    final locDict = _locationTranslations[_currentLang] ?? _locationTranslations['en'] ?? {};
    if (locDict.containsKey(key)) {
      return locDict[key]!;
    }
    if (_locationTranslations['en']?.containsKey(key) == true) {
      return _locationTranslations['en']![key]!;
    }

    // 3. Check main translations
    final dict = _translations[_currentLang] ?? _translations['en'] ?? {};
    return dict[key] ?? _translations['en']?[key] ?? key;
  }
}


typedef I1nService = I18nService;
